import { createReadStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import { Transform, Writable } from 'node:stream';

let words = 0;
let leftover = '';

await pipeline(
  createReadStream('big.txt', { encoding: 'utf8' }),
  new Transform({
    transform(chunk, _enc, cb) {
      const text = leftover + chunk;
      const parts = text.split(/\s+/);
      leftover = parts.pop();                  // a word may be cut at the chunk edge
      cb(null, String(parts.filter(Boolean).length));
    },
    flush(cb) { cb(null, leftover ? '1' : '0'); },
  }),
  new Writable({
    write(chunk, _enc, cb) { words += Number(chunk.toString()); cb(); },
  }),
);
console.log('words:', words);

