app.get('/api/v1/posts', async (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 20, 100);     // cap the page size
  const after = req.query.after;                                  // cursor = last seen id

  const filter = after ? { _id: { $lt: after } } : {};
  const items = await Post.find(filter).sort({ _id: -1 }).limit(limit + 1).lean();

  const hasMore = items.length > limit;
  if (hasMore) items.pop();

  res.json({ items, nextCursor: hasMore ? items.at(-1)._id : null });
});

